// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address k, bool status) public {
        // Ensure owner is set (onlyOwner uses _contractOwner which is default address(0) in setUp)
        // Since onlyOwner uses the stored _contractOwner (default 0), we prank as address(0) which is the owner
        vm.prank(address(0));
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.setApprovedLogger.selector, k, status)
        );
        if (success) {
            assertTrue(c.approvedToLog(k) == status);
        } else {
            // If call reverted, the mapping should remain unchanged
            // But we can't know initial value; we just assert nothing about it
            // This branch is unlikely; to avoid vacuous truth, we ensure at least one success
            vm.assume(false);
        }
    }
}

